         breed_name ?breedName.
  {
    SELECT (COUNT(DISTINCT ?dog) AS ?dogCount) WHERE {
      ?dog a dogs.
      ?dog ref-breed_code ?breed.
    }
    ORDER BY ?dogCount
  }
